219	// validObjectKey reports whether key is 1..1024 bytes of valid UTF-8 with no
220	// control characters.
221	func validObjectKey(key string) bool {
222		if len(key) == 0 || len(key) > 1024 || !utf8.ValidString(key) {
223			return false
224		}
225		for _, r := range key {
226			if unicode.IsControl(r) {
227				return false
228			}
229		}
230		return true
231	}
