233	// extractMetadata collects the X-Vaultgrid-Meta-* request headers into a
234	// metadata map keyed by the suffix after the prefix. A header with an empty
235	// suffix or a value that is not valid UTF-8 or carries control characters
236	// makes the whole request invalid.
237	func extractMetadata(h http.Header) (map[string]string, bool) {
238		meta := make(map[string]string)
239		for name, values := range h {
240			suffix, ok := strings.CutPrefix(name, metaPrefix)
241			if !ok {
242				continue
243			}
244			if suffix == "" {
245				return nil, false
246			}
247			for _, v := range values {
248				if !utf8.ValidString(v) {
249					return nil, false
250				}
251				for _, r := range v {
252					if unicode.IsControl(r) {
253						return nil, false
254					}
255				}
256			}
257			meta[suffix] = strings.Join(values, ", ")
258		}
259		return meta, true
260	}
