262	// parsePrecondition validates the conditional-write headers. It returns the
263	// If-Match etag ("" when absent) and whether If-None-Match: * was given. ok
264	// is false when both headers are present or either has an unsupported form.
265	func parsePrecondition(h http.Header) (ifMatch string, ifNoneMatchStar, ok bool) {
266		matches, hasMatch := h["If-Match"]
267		noneMatches, hasNoneMatch := h["If-None-Match"]
268		if hasMatch && hasNoneMatch {
269			return "", false, false
270		}
271		if hasMatch {
272			if len(matches) != 1 || !isQuotedETag(matches[0]) {
273				return "", false, false
274			}
275			return matches[0], false, true
276		}
277		if hasNoneMatch {
278			if len(noneMatches) != 1 || noneMatches[0] != "*" {
279				return "", false, false
280			}
281			return "", true, true
282		}
283		return "", false, true
284	}
285	
286	// isQuotedETag reports whether v looks like a quoted hex etag, e.g.
287	// "9f86d081...". The content is not checked against any object here.
288	func isQuotedETag(v string) bool {
289		if len(v) < 2 || v[0] != '"' || v[len(v)-1] != '"' {
290			return false
291		}
292		inner := v[1 : len(v)-1]
293		if inner == "" {
294			return false
295		}
296		for _, c := range inner {
297			if !('0' <= c && c <= '9' || 'a' <= c && c <= 'f') {
298				return false
299			}
300		}
301		return true
302	}
303	
304	func etagOf(content []byte) string {
305		sum := sha256.Sum256(content)
306		return `"` + hex.EncodeToString(sum[:]) + `"`
307	}
308	
309	func (s *store) putObject(w http.ResponseWriter, r *http.Request, bucketID, key string) {
310		if !validID(bucketID) || !validObjectKey(key) {
311			writeError(w, http.StatusBadRequest, "invalid_request")
312			return
313		}
314		if r.URL.RawQuery != "" {
315			writeError(w, http.StatusBadRequest, "invalid_request")
316			return
317		}
318		metadata, ok := extractMetadata(r.Header)
319		if !ok {
320			writeError(w, http.StatusBadRequest, "invalid_request")
321			return
322		}
323		ifMatch, ifNoneMatchStar, ok := parsePrecondition(r.Header)
324		if !ok {
325			writeError(w, http.StatusBadRequest, "invalid_request")
326			return
327		}
328		content, err := io.ReadAll(r.Body)
329		if err != nil {
330			writeError(w, http.StatusBadRequest, "invalid_request")
331			return
332		}
333		etag := etagOf(content)
334		size := int64(len(content))
335	
336		s.mu.Lock()
337		defer s.mu.Unlock()
338		b, ok := s.buckets[bucketID]
339		if !ok {
340			writeError(w, http.StatusNotFound, "bucket_not_found")
341			return
342		}
343		existing := b.objects[key]
344		if ifMatch != "" && (existing == nil || existing.etag != ifMatch) {
345			writeError(w, http.StatusPreconditionFailed, "precondition_failed")
346			return
347		}
348		if ifNoneMatchStar && existing != nil {
349			writeError(w, http.StatusPreconditionFailed, "precondition_failed")
350			return
351		}
352		var oldSize int64
353		if existing != nil {
354			oldSize = existing.sizeBytes
355		}
356		p := s.pools[b.poolID]
357		// The store lock makes the capacity check and the charge atomic, so
358		// concurrent writes can never overcommit the pool, and a failed write
359		// leaves the old object and its metadata untouched.
360		if p.allocated() > p.rawCapacity-(size-oldSize) {
361			writeError(w, http.StatusConflict, "insufficient_capacity")
362			return
363		}
364		b.objects[key] = &object{key: key, content: content, metadata: metadata, etag: etag, sizeBytes: size}
365		p.objectBytes += size - oldSize
366		status := http.StatusCreated
367		if existing != nil {
368			status = http.StatusOK
369		}
370		w.Header().Set("ETag", etag)
371		writeJSON(w, status, b.objects[key].view())
372	}
373	
374	// getObject serves both GET and HEAD; headOnly suppresses the body.
375	func (s *store) getObject(w http.ResponseWriter, r *http.Request, bucketID, key string, headOnly bool) {
376		if !validID(bucketID) || !validObjectKey(key) {
377			writeError(w, http.StatusBadRequest, "invalid_request")
378			return
379		}
380		if r.URL.RawQuery != "" {
381			writeError(w, http.StatusBadRequest, "invalid_request")
382			return
383		}
384		s.mu.RLock()
385		b, ok := s.buckets[bucketID]
386		var o *object
387		if ok {
388			o = b.objects[key]
389		}
390		s.mu.RUnlock()
391		if !ok {
392			writeError(w, http.StatusNotFound, "bucket_not_found")
393			return
394		}
395		if o == nil {
396			writeError(w, http.StatusNotFound, "object_not_found")
397			return
398		}
399		for name, value := range o.metadata {
400			w.Header().Set(metaPrefix+name, value)
401		}
402		w.Header().Set("ETag", o.etag)
403		w.Header().Set("Content-Type", "application/octet-stream")
404		w.Header().Set("Content-Length", strconv.FormatInt(o.sizeBytes, 10))
405		w.WriteHeader(http.StatusOK)
406		if !headOnly {
407			_, _ = w.Write(o.content)
408		}
409	}
410	
411	func (s *store) deleteObject(w http.ResponseWriter, r *http.Request, bucketID, key string) {
412		if !validID(bucketID) || !validObjectKey(key) {
413			writeError(w, http.StatusBadRequest, "invalid_request")
414			return
415		}
416		if r.URL.RawQuery != "" {
417			writeError(w, http.StatusBadRequest, "invalid_request")
418			return
419		}
420		s.mu.Lock()
421		defer s.mu.Unlock()
422		b, ok := s.buckets[bucketID]
423		if !ok {
424			writeError(w, http.StatusNotFound, "bucket_not_found")
425			return
426		}
427		// Deleting an unknown or already-deleted object is a success.
428		if o, exists := b.objects[key]; exists {
429			s.pools[b.poolID].objectBytes -= o.sizeBytes
430			delete(b.objects, key)
431		}
432		w.WriteHeader(http.StatusNoContent)
433	}
434	
435	// parsePrefixQuery accepts an empty query or exactly one "prefix=<value>"
436	// pair. Duplicated or unknown parameters yield ok=false.
437	func parsePrefixQuery(raw string) (string, bool) {
438		if raw == "" {
439			return "", true
440		}
441		var prefix string
442		found := false
443		for _, pair := range strings.Split(raw, "&") {
444			k, value, ok := strings.Cut(pair, "=")
445			if !ok {
446				return "", false
447			}
448			decodedKey, err := url.QueryUnescape(k)
449			if err != nil || decodedKey != "prefix" || found {
450				return "", false
451			}
452			decodedValue, err := url.QueryUnescape(value)
453			if err != nil {
454				return "", false
455			}
456			prefix, found = decodedValue, true
457		}
458		return prefix, found
459	}
460	
461	func (s *store) listObjects(w http.ResponseWriter, r *http.Request, bucketID string) {
462		prefix, ok := parsePrefixQuery(r.URL.RawQuery)
463		if !ok || !validID(bucketID) {
464			writeError(w, http.StatusBadRequest, "invalid_request")
465			return
466		}
467		s.mu.RLock()
468		b, ok := s.buckets[bucketID]
469		var items []objectView
470		if ok {
471			keys := make([]string, 0, len(b.objects))
472			for k := range b.objects {
473				keys = append(keys, k)
474			}
475			sort.Strings(keys)
476			items = make([]objectView, 0, len(keys))
477			for _, k := range keys {
478				if strings.HasPrefix(k, prefix) {
479					items = append(items, b.objects[k].view())
480				}
481			}
482		}
483		s.mu.RUnlock()
484		if !ok {
485			writeError(w, http.StatusNotFound, "bucket_not_found")
486			return
487		}
488		writeJSON(w, http.StatusOK, map[string]any{"items": items})
489	}
