228		// expectedGeneration is the single accepted query parameter; it must be
229		// present exactly once. Parse the raw string manually so malformed or
230		// duplicated parameters cannot be silently discarded.
231		gen, ok := parseGenerationQuery(r.URL.RawQuery)
