238		defer s.mu.Unlock()
239		v, exists := s.volumes[volumeID]
240		if !exists {
241			writeError(w, http.StatusNotFound, "volume_not_found")
242			return
243		}
244		if v.generation != gen {
245			writeError(w, http.StatusConflict, "stale_generation")
246			return
247		}
248		wasBound := v.binding != ""
249		v.binding = ""
250		if wasBound {
251			v.generation++
252		}
253		w.WriteHeader(http.StatusNoContent)
254	}
