256	// parseGenerationQuery accepts exactly one "expectedGeneration=<non-neg-int>"
257	// pair. Missing, empty, duplicated or extra parameters yield ok=false.
258	func parseGenerationQuery(raw string) (int64, bool) {
259		if raw == "" {
260			return 0, false
261		}
262		var gen int64
263		found := false
264		for _, pair := range strings.Split(raw, "&") {
265			key, value, ok := strings.Cut(pair, "=")
266			if !ok {
267				return 0, false
268			}
269			decodedKey, err := url.QueryUnescape(key)
270			if err != nil {
271				return 0, false
272			}
273			if decodedKey != "expectedGeneration" {
274				return 0, false
275			}
276			if found {
277				return 0, false
278			}
279			decodedValue, err := url.QueryUnescape(value)
280			if err != nil {
281				return 0, false
282			}
283			parsed, err := strconv.ParseInt(decodedValue, 10, 64)
284			if err != nil || parsed < 0 {
285				return 0, false
286			}
287			gen, found = parsed, true
288		}
289		return gen, found
290	}
