package server

import (
	"net/http"
	"net/url"
	"sort"
	"strconv"
	"strings"
)

type createVolumeInput struct {
	ID        string `json:"id"`
	PoolID    string `json:"poolId"`
	SizeBytes int64  `json:"sizeBytes"`
}

type bindingInput struct {
	NodeID             string `json:"nodeId"`
	ExpectedGeneration *int64 `json:"expectedGeneration"`
}

// bindingView is the public representation of a volume binding.
type bindingView struct {
	NodeID string `json:"nodeId"`
}

// volumeView is the public representation of a volume.
type volumeView struct {
	ID         string       `json:"id"`
	PoolID     string       `json:"poolId"`
	SizeBytes  int64        `json:"sizeBytes"`
	Generation int64        `json:"generation"`
	Binding    *bindingView `json:"binding"`
}

func (v *volume) view() volumeView {
	view := volumeView{
		ID:         v.id,
		PoolID:     v.poolID,
		SizeBytes:  v.sizeBytes,
		Generation: v.generation,
		Binding:    nil,
	}
	if v.binding != "" {
		view.Binding = &bindingView{NodeID: v.binding}
	}
	return view
}

// routeVolumes dispatches /v1/volumes and its sub-paths.
func (s *store) routeVolumes(w http.ResponseWriter, r *http.Request) {
	parts := splitPath(r.URL.Path, volumePath)
	for _, seg := range parts {
		if seg == "" {
			writeError(w, http.StatusNotFound, "not_found")
			return
		}
	}
	switch {
	case len(parts) == 0:
		switch r.Method {
		case http.MethodGet:
			s.listVolumes(w)
		case http.MethodPost:
			s.createVolume(w, r)
		default:
			methodNotAllowed(w, http.MethodGet, http.MethodPost)
		}
	case len(parts) == 1:
		switch r.Method {
		case http.MethodGet:
			s.getVolume(w, parts[0])
		case http.MethodDelete:
			s.deleteVolume(w, parts[0])
		default:
			methodNotAllowed(w, http.MethodGet, http.MethodDelete)
		}
	case len(parts) == 2 && parts[1] == "binding":
		switch r.Method {
		case http.MethodPut:
			s.putBinding(w, r, parts[0])
		case http.MethodDelete:
			s.deleteBinding(w, r, parts[0])
		default:
			methodNotAllowed(w, http.MethodPut, http.MethodDelete)
		}
	case len(parts) == 2 && parts[1] == "snapshots":
		if r.Method != http.MethodPost {
			methodNotAllowed(w, http.MethodPost)
			return
		}
		s.createSnapshot(w, r, parts[0])
	default:
		writeError(w, http.StatusNotFound, "not_found")
	}
}

func (s *store) listVolumes(w http.ResponseWriter) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	ids := make([]string, 0, len(s.volumes))
	for id := range s.volumes {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	items := make([]volumeView, 0, len(ids))
	for _, id := range ids {
		items = append(items, s.volumes[id].view())
	}
	writeJSON(w, http.StatusOK, map[string]any{"items": items})
}

func (s *store) getVolume(w http.ResponseWriter, id string) {
	if !validID(id) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.RLock()
	v, ok := s.volumes[id]
	var view volumeView
	if ok {
		view = v.view()
	}
	s.mu.RUnlock()
	if !ok {
		writeError(w, http.StatusNotFound, "volume_not_found")
		return
	}
	writeJSON(w, http.StatusOK, view)
}

func (s *store) createVolume(w http.ResponseWriter, r *http.Request) {
	var in createVolumeInput
	if !decodeRequest(r, &in) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	if !validID(in.ID) || !validID(in.PoolID) || in.SizeBytes <= 0 {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	if existing, dup := s.volumes[in.ID]; dup {
		if existing.poolID == in.PoolID && existing.sizeBytes == in.SizeBytes {
			writeJSON(w, http.StatusOK, existing.view())
			return
		}
		writeError(w, http.StatusConflict, "volume_exists")
		return
	}
	p, ok := s.pools[in.PoolID]
	if !ok {
		writeError(w, http.StatusNotFound, "pool_not_found")
		return
	}
	// Holding the store lock makes the capacity check and the reservation
	// atomic, so concurrent creates can never overcommit the pool.
	if p.allocated() > p.rawCapacity-in.SizeBytes {
		writeError(w, http.StatusConflict, "insufficient_capacity")
		return
	}
	v := &volume{id: in.ID, poolID: in.PoolID, sizeBytes: in.SizeBytes}
	s.volumes[in.ID] = v
	p.volumeBytes += in.SizeBytes
	writeJSON(w, http.StatusCreated, v.view())
}

func (s *store) deleteVolume(w http.ResponseWriter, id string) {
	if !validID(id) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	v, ok := s.volumes[id]
	if !ok {
		writeError(w, http.StatusNotFound, "volume_not_found")
		return
	}
	if v.binding != "" {
		writeError(w, http.StatusConflict, "volume_in_use")
		return
	}
	s.pools[v.poolID].volumeBytes -= v.sizeBytes
	delete(s.volumes, id)
	w.WriteHeader(http.StatusNoContent)
}

func (s *store) putBinding(w http.ResponseWriter, r *http.Request, volumeID string) {
	var in bindingInput
	if !decodeRequest(r, &in) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	if !validID(volumeID) || !validID(in.NodeID) || in.ExpectedGeneration == nil || *in.ExpectedGeneration < 0 {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	expected := *in.ExpectedGeneration

	s.mu.Lock()
	defer s.mu.Unlock()
	v, ok := s.volumes[volumeID]
	if !ok {
		writeError(w, http.StatusNotFound, "volume_not_found")
		return
	}
	if v.generation != expected {
		writeError(w, http.StatusConflict, "stale_generation")
		return
	}
	switch {
	case v.binding == "":
		v.binding = in.NodeID
		v.generation++
	case v.binding != in.NodeID:
		writeError(w, http.StatusConflict, "volume_already_bound")
		return
	}
	// A same-node, same-generation PUT is an idempotent no-op that returns
	// the current representation without bumping the generation.
	writeJSON(w, http.StatusOK, v.view())
}

func (s *store) deleteBinding(w http.ResponseWriter, r *http.Request, volumeID string) {
	// expectedGeneration is the single accepted query parameter; it must be
	// present exactly once. Parse the raw string manually so malformed or
	// duplicated parameters cannot be silently discarded.
	gen, ok := parseGenerationQuery(r.URL.RawQuery)
	if !ok || !validID(volumeID) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	v, exists := s.volumes[volumeID]
	if !exists {
		writeError(w, http.StatusNotFound, "volume_not_found")
		return
	}
	if v.generation != gen {
		writeError(w, http.StatusConflict, "stale_generation")
		return
	}
	wasBound := v.binding != ""
	v.binding = ""
	if wasBound {
		v.generation++
	}
	w.WriteHeader(http.StatusNoContent)
}

// parseGenerationQuery accepts exactly one "expectedGeneration=<non-neg-int>"
// pair. Missing, empty, duplicated or extra parameters yield ok=false.
func parseGenerationQuery(raw string) (int64, bool) {
	if raw == "" {
		return 0, false
	}
	var gen int64
	found := false
	for _, pair := range strings.Split(raw, "&") {
		key, value, ok := strings.Cut(pair, "=")
		if !ok {
			return 0, false
		}
		decodedKey, err := url.QueryUnescape(key)
		if err != nil {
			return 0, false
		}
		if decodedKey != "expectedGeneration" {
			return 0, false
		}
		if found {
			return 0, false
		}
		decodedValue, err := url.QueryUnescape(value)
		if err != nil {
			return 0, false
		}
		parsed, err := strconv.ParseInt(decodedValue, 10, 64)
		if err != nil || parsed < 0 {
			return 0, false
		}
		gen, found = parsed, true
	}
	return gen, found
}

package server

import (
	"fmt"
	"net/http"
	"net/url"
	"sort"
	"strings"
)

// capacityReportItem is the per-pool row of the capacity report.
type capacityReportItem struct {
	PoolID           string `json:"poolId"`
	RawCapacityBytes int64  `json:"rawCapacityBytes"`
	ReservationBytes int64  `json:"reservationBytes"`
	VolumeBytes      int64  `json:"volumeBytes"`
	SnapshotBytes    int64  `json:"snapshotBytes"`
	ObjectBytes      int64  `json:"objectBytes"`
	AllocatedBytes   int64  `json:"allocatedBytes"`
	AvailableBytes   int64  `json:"availableBytes"`
}

// capacityReportSummary is the aggregate over every reported pool; it carries
// the same fields as a pool row except poolId.
type capacityReportSummary struct {
	RawCapacityBytes int64 `json:"rawCapacityBytes"`
	ReservationBytes int64 `json:"reservationBytes"`
	VolumeBytes      int64 `json:"volumeBytes"`
	SnapshotBytes    int64 `json:"snapshotBytes"`
	ObjectBytes      int64 `json:"objectBytes"`
	AllocatedBytes   int64 `json:"allocatedBytes"`
	AvailableBytes   int64 `json:"availableBytes"`
}

// csvHeader is the fixed first line of the CSV report. Pool ids are
// restricted to A-Za-z0-9._- so no field ever needs quoting.
const csvHeader = "poolId,rawCapacityBytes,reservationBytes,volumeBytes,snapshotBytes,objectBytes,allocatedBytes,availableBytes"

// parseCapacityReportQuery accepts an empty query or any combination of the
// "format" and "poolId" parameters, each given at most once and always with
// a value. Duplicated, unknown or value-less parameters yield ok=false.
func parseCapacityReportQuery(raw string) (format, poolID string, hasPool, ok bool) {
	format = "json"
	if raw == "" {
		return format, "", false, true
	}
	seenFormat, seenPool := false, false
	for _, pair := range strings.Split(raw, "&") {
		k, value, found := strings.Cut(pair, "=")
		if !found {
			return "", "", false, false
		}
		key, err := url.QueryUnescape(k)
		if err != nil {
			return "", "", false, false
		}
		decoded, err := url.QueryUnescape(value)
		if err != nil {
			return "", "", false, false
		}
		switch key {
		case "format":
			if seenFormat {
				return "", "", false, false
			}
			seenFormat = true
			format = decoded
		case "poolId":
			if seenPool {
				return "", "", false, false
			}
			seenPool = true
			poolID = decoded
		default:
			return "", "", false, false
		}
	}
	return format, poolID, seenPool, true
}

// capacityReport handles GET /v1/capacity-report. The whole report is built
// under a single read lock, so every row and the summary describe one
// consistent state even while other requests mutate the store.
func (s *store) capacityReport(w http.ResponseWriter, r *http.Request) {
	format, poolID, hasPool, ok := parseCapacityReportQuery(r.URL.RawQuery)
	if !ok || (format != "json" && format != "csv") || (hasPool && !validID(poolID)) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}

	s.mu.RLock()
	var ids []string
	if hasPool {
		if _, exists := s.pools[poolID]; !exists {
			s.mu.RUnlock()
			writeError(w, http.StatusNotFound, "pool_not_found")
			return
		}
		ids = []string{poolID}
	} else {
		ids = make([]string, 0, len(s.pools))
		for id := range s.pools {
			ids = append(ids, id)
		}
		sort.Strings(ids)
	}
	items := make([]capacityReportItem, 0, len(ids))
	var summary capacityReportSummary
	for _, id := range ids {
		p := s.pools[id]
		var reservationBytes int64
		for _, res := range p.reservations {
			reservationBytes += res.bytes
		}
		allocated := p.allocated()
		item := capacityReportItem{
			PoolID:           p.id,
			RawCapacityBytes: p.rawCapacity,
			ReservationBytes: reservationBytes,
			VolumeBytes:      p.volumeBytes,
			SnapshotBytes:    p.snapshotBytes,
			ObjectBytes:      p.objectBytes,
			AllocatedBytes:   allocated,
			AvailableBytes:   p.rawCapacity - allocated,
		}
		items = append(items, item)
		summary.RawCapacityBytes += item.RawCapacityBytes
		summary.ReservationBytes += item.ReservationBytes
		summary.VolumeBytes += item.VolumeBytes
		summary.SnapshotBytes += item.SnapshotBytes
		summary.ObjectBytes += item.ObjectBytes
		summary.AllocatedBytes += item.AllocatedBytes
		summary.AvailableBytes += item.AvailableBytes
	}
	s.mu.RUnlock()

	if format == "csv" {
		var b strings.Builder
		b.WriteString(csvHeader)
		b.WriteByte('\n')
		for _, it := range items {
			fmt.Fprintf(&b, "%s,%d,%d,%d,%d,%d,%d,%d\n",
				it.PoolID, it.RawCapacityBytes, it.ReservationBytes, it.VolumeBytes,
				it.SnapshotBytes, it.ObjectBytes, it.AllocatedBytes, it.AvailableBytes)
		}
		w.Header().Set("Content-Type", "text/csv; charset=utf-8")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(b.String()))
		return
	}
	writeJSON(w, http.StatusOK, struct {
		Summary capacityReportSummary `json:"summary"`
		Items   []capacityReportItem  `json:"items"`
	}{Summary: summary, Items: items})
}

