226	// the exact sum of the items.
227	func TestCapacityReportConsistentUnderConcurrency(t *testing.T) {
228		h := Handler()
229		createPool(t, h, `{"id":"cp","devices":[{"id":"d","capacityBytes":100000,"faultDomain":"fd"}]}`)
230	
231		var wg sync.WaitGroup
232		stop := make(chan struct{})
233		for i := 0; i < 8; i++ {
234			wg.Add(1)
235			go func(i int) {
236				defer wg.Done()
237				id := fmt.Sprintf("r%d", i)
238				for {
239					select {
240					case <-stop:
241						return
242					default:
243					}
244					reserve(t, h, "cp", fmt.Sprintf(`{"requestId":%q,"bytes":10}`, id))
245					do(h, http.MethodDelete, "/v1/storage-pools/cp/reservations/"+id, "")
246				}
247			}(i)
248		}
249	
250		for i := 0; i < 200; i++ {
251			v := getReport(t, h, "/v1/capacity-report")
252			items := v["items"].([]any)
253			var sumAlloc, sumAvail, sumRaw float64
254			for _, raw := range items {
255				item := raw.(map[string]any)
256				alloc := item["allocatedBytes"].(float64)
257				parts := item["reservationBytes"].(float64) + item["volumeBytes"].(float64) +
258					item["snapshotBytes"].(float64) + item["objectBytes"].(float64)
259				if alloc != parts {
260					t.Fatalf("allocated %v != category sum %v in %v", alloc, parts, item)
261				}
262				avail := item["availableBytes"].(float64)
263				if avail != item["rawCapacityBytes"].(float64)-alloc || avail < 0 {
264					t.Fatalf("available %v inconsistent in %v", avail, item)
265				}
266				sumAlloc += alloc
267				sumAvail += avail
268				sumRaw += item["rawCapacityBytes"].(float64)
269			}
270			summary := v["summary"].(map[string]any)
271			if summary["allocatedBytes"].(float64) != sumAlloc ||
272				summary["availableBytes"].(float64) != sumAvail ||
273				summary["rawCapacityBytes"].(float64) != sumRaw {
274				t.Fatalf("summary %v does not match items %v", summary, items)
275			}
276		}
277		close(stop)
278		wg.Wait()
279	}
