291		checkItem(t, v["items"].([]any)[0].(map[string]any), "pool-a", 1500, 100, 200, 0, 0)
292	
293		// Idempotent retry does not double count.
294		reserve(t, h, "pool-a", `{"requestId":"r1","bytes":100}`)
295		v = getReport(t, h, "/v1/capacity-report")
296		checkItem(t, v["items"].([]any)[0].(map[string]any), "pool-a", 1500, 100, 200, 0, 0)
297	
298		// Deletions release their class.
299		do(h, http.MethodDelete, "/v1/storage-pools/pool-a/reservations/r1", "")
300		do(h, http.MethodDelete, "/v1/volumes/vol-1", "")
301		v = getReport(t, h, "/v1/capacity-report")
302		checkItem(t, v["items"].([]any)[0].(map[string]any), "pool-a", 1500, 0, 0, 0, 0)
303		checkSummary(t, v["summary"].(map[string]any), 1500, 0, 0, 0, 0)
304	}
