310		body := rec(h, "/v1/capacity-report?poolId=pool-a")
311	
312		var decoded map[string]json.RawMessage
313		if err := json.Unmarshal([]byte(body), &decoded); err != nil {
314			t.Fatalf("report not JSON: %v", err)
315		}
316		if len(decoded) != 2 || decoded["summary"] == nil || decoded["items"] == nil {
317			t.Fatalf("top-level keys = %v", decoded)
318		}
319		var item map[string]json.RawMessage
320		var items []json.RawMessage
321		if err := json.Unmarshal(decoded["items"], &items); err != nil || len(items) != 1 {
322			t.Fatalf("items = %s", decoded["items"])
323		}
324		if err := json.Unmarshal(items[0], &item); err != nil {
325			t.Fatalf("item not JSON: %v", err)
326		}
327		wantKeys := []string{"poolId", "rawCapacityBytes", "reservationBytes", "volumeBytes",
328			"snapshotBytes", "objectBytes", "allocatedBytes", "availableBytes"}
329		if len(item) != len(wantKeys) {
330			t.Fatalf("item keys = %v", item)
331		}
332		for _, k := range wantKeys {
333			if item[k] == nil {
334				t.Fatalf("item missing key %q: %v", k, item)
335			}
336		}
337	}
