package server

import (
	"net/http"
	"net/url"
	"strconv"
	"strings"
)

// auditAction enumerates the state-changing operations recorded in the audit
// log. Read-only requests, failures, read-only and successful no-ops are never
// recorded.
type auditAction string

const (
	auditPoolCreated        auditAction = "pool.created"
	auditPoolDeleted        auditAction = "pool.deleted"
	auditReservationCreated auditAction = "reservation.created"
	auditReservationDeleted auditAction = "reservation.deleted"
	auditVolumeCreated      auditAction = "snapshot.created"
	auditVolumeDeleted      auditAction = "volume.deleted"
	auditVolumeBound        auditAction = "volume.bound"
	auditVolumeUnbound      auditAction = "volume.unbound"
	auditSnapshotCreated    auditAction = "snapshot.created"
	auditSnapshotDeleted    auditAction = "snapshot.deleted"
	auditCloneCreated       auditAction = "clone.created"
	auditBucketCreated      auditAction = "bucket.created"
	auditBucketDeleted      auditAction = "bucket.deleted"
	auditObjectCreated      auditAction = "object.created"
	auditObjectOverwritten  auditAction = "object.overwritten"
	auditObjectDeleted      auditAction = "object.deleted"
)

// auditEventView is the public representation of an audit event.
type auditEventView struct {
	Sequence   int64  `json:"sequence"`
	Action     string `json:"action"`
	Resource   string `json:"resource"`
	PoolID     string `json:"poolId"`
	BytesDelta int64  `json:"bytesDelta"`
}

// auditEvent is one entry of the in-memory audit log. Events are appended
// while holding the store write lock, together with the business state and
// capacity counters they describe, so the log is atomically committed with the
// change. The log lives in memory and is wiped on restart.
type auditEvent struct {
	sequence   int64
	action     auditAction
	resource   string
	poolID     string
	bytesDelta int64
}

func (e *auditEvent) view() auditEventView {
	return auditEventView{
		Sequence:   e.sequence,
		Action:     string(e.action),
		Resource:   e.resource,
		PoolID:     e.poolID,
		BytesDelta: e.bytesDelta,
	}
}

// appendAudit assigns the next sequence and appends an event. The caller must
// hold s.mu (write intent); appending under the same critical section as the
// mutation numbers concurrent commits in commit order and makes the event
// queryable as soon as the response is returned.
func (s *store) appendAudit(action auditAction, resource, poolID string, bytesDelta int64) {
	s.auditSeq++
	s.auditEvents = append(s.auditEvents, auditEvent{
		sequence:   s.auditSeq,
		action:     action,
		resource:   resource,
		poolID:     poolID,
		bytesDelta: bytesDelta,
	})
}

// Public resource paths recorded on events.
const (
	resPathPools       = "/v1/storage-pools"
	resPathVolumes     = "/v1/volumes"
	resPathSnapshots   = "/v1/snapshots"
	resPathBuckets     = "/v1/buckets"
	resPathReservations = "/v1/storage-pools/{id}/reservations"
)

// resourceURL builds a public resource path from segments.
func resourceURL(segments ...string) string {
	return strings.Join(segments, "/")
}

// auditEventsPath is the route constant for the audit events endpoint.
const auditEventsPath = "/v1/audit-events"

// parseAuditEventsQuery accepts an empty query or any combination of the
// "after", "limit" and "poolId" parameters, each given at most once and always
// with a value. Duplicated, unknown or value-less parameters yield ok=false.
// It also enforces the shape of each value: after a non-negative decimal
// integer, limit an integer in 1..1000, poolId a legal id.
func parseAuditEventsQuery(raw string) (after int64, limit int, poolID string, ok bool) {
	after = 0
	limit = 100
	if raw == "" {
		return 0, 100, "", true
	}
	seenAfter, seenLimit, seenPool := false, false, false
	for _, pair := range strings.Split(raw, "&") {
		k, value, found := strings.Cut(pair, "=")
		if !found {
			return 0, 0, "", false
		}
		key, err := url.QueryUnescape(k)
		if err != nil {
			return 0, 0, "", false
		}
		decoded, err := url.QueryUnescape(value)
		if err != nil {
			return 0, 0, "", false
		}
		switch key {
		case "after":
			if seenAfter {
				return 0, 0, "", false
			}
			seenAfter = true
			// after must be a non-negative decimal integer with no sign or
			// spaces; ParseInt handles range and a leading "+".
			n, err := strconv.ParseInt(decoded, 10, 64)
			if err != nil || n < 0 || !isDecimalInt(decoded) || decoded == "" {
				return 0, 0, "", false
			}
			after = n
		case "limit":
			if seenLimit {
				return 0, 0, "", false
			}
		case "poolId":
			if seenPool {
				return 0, 0, "", false
			}
			seenPool = true
			poolID = decoded
		default:
			return 0, 0, "", false
		}
	}
	return after, limit, poolID, true
}

func isDecimalInt(s string) bool {
	if s == "" {
		return false
	}
	for i, c := range s {
		if i == 0 && c == '-' {
			continue
		}
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

