	defer s.mu.Unlock()
	if existing, dup := s.volumes[in.ID]; dup {
		if existing.poolID == in.PoolID && existing.sizeBytes == in.SizeBytes {
			writeJSON(w, http.StatusOK, existing.view())
			return
		}
		writeError(w, http.StatusConflict, "volume_exists")
		return
