func TestAuditEventsMethodAndPath(t *testing.T) {
	h := Handler()
	for _, method := range []string{http.MethodPost, http.MethodPut, http.MethodDelete, http.MethodPatch, http.MethodHead} {
		rec := do(h, method, "/v1/audit-events", "")
